argv:
$ErrorActionPreference='Stop'
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class Win32Ctl {
  [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd,int nCmdShow);
  [DllImport("user32.dll")] public static extern bool BringWindowToTop(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern IntPtr SetFocus(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, IntPtr lpdwProcessId);
  [DllImport("kernel32.dll")] public static extern uint GetCurrentThreadId();
  [DllImport("user32.dll")] public static extern bool AttachThreadInput(uint idAttach,uint idAttachTo,bool fAttach);
}
"@
Add-Type -AssemblyName System.Windows.Forms
$h=[IntPtr]67948
[Win32Ctl]::ShowWindowAsync($h,9) | Out-Null
$targetThread=[Win32Ctl]::GetWindowThreadProcessId($h,[IntPtr]::Zero)
$currentThread=[Win32Ctl]::GetCurrentThreadId()
[Win32Ctl]::AttachThreadInput($currentThread,$targetThread,$true) | Out-Null
[Win32Ctl]::BringWindowToTop($h) | Out-Null
[Win32Ctl]::SetForegroundWindow($h) | Out-Null
[Win32Ctl]::SetFocus($h) | Out-Null
[Win32Ctl]::AttachThreadInput($currentThread,$targetThread,$false) | Out-Null
Start-Sleep -Milliseconds 500
$fg=[Win32Ctl]::GetForegroundWindow().ToInt64()
Write-Output "foreground=$fg"
if($fg -ne 67948){ throw "Foreground mismatch $fg" }
[System.Windows.Forms.SendKeys]::SendWait('^l')
Start-Sleep -Milliseconds 150
[System.Windows.Forms.SendKeys]::SendWait('https://bugbountyfoto6.files.com/ui/users')
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 3
